    Assertions.assertEquals('1', inputBuffer.read());
    Assertions.assertEquals('2', inputBuffer.read());
    final int bytesRead2 = inputBuffer.read(tmp, 0, tmp.length);
    Assertions.assertEquals(8, bytesRead2);
