    Assertions.assertEquals(-1, inputBuffer.read(tmp, 0, tmp.length));
    Assertions.assertEquals(-1, inputBuffer.read(tmp, 0, tmp.length));
    Assertions.assertEquals(-1, inputBuffer.read());
